    raetsel: {"fehlerbild":{"titel":"Finde die 10 Fehler","a":"magazin/raetsel/nr10-herbstkueche-a.svg","b":"magazin/raetsel/nr10-herbstkueche-b.svg","loesung":"magazin/raetsel/nr10-herbstkueche-loesung.svg","fehler":[[200,43,22,"Der Lampenschirm hat eine andere Farbe"],[120,78,20,"Am Baum vor dem Fenster ist ein Teil noch grün"],[45,112,13,"Die Kerze auf der Fensterbank brennt nicht"],[320,57,20,"Auf dem Regal fehlt ein Teller"],[80,143,13,"Dem großen Kürbis fehlt der Stiel"],[135,186,20,"Der kleine Kürbis ist grün statt orange"],[171,153,17,"Im Glas steckt ein Rosmarinzweig weniger"],[247,136,25,"Die Kelle im Topf fehlt"],[352,178,14,"In der Suppenschale fehlt der Sahneklecks"],[215,246,14,"In der Kiste liegt ein Apfel weniger"]]},"kreuzwort":{"titel":"Herbstküche","zeilen":[".HALLOWEEN...P...","......I...S..I...","KERNOEL..APFELMUS","......D...A..Z...","..L...S.K.E..R...","..A...C.U.T.LAUB.","..T.P.H.E.Z..H...","..E.F.W.R.L..M...",".PREISELBEERE...Z","..N.F.I.I..O....W","..E.F.N.S..S..R.I","....E...K..MARONE",".PUERIEREN.A..T.B","....L...R..R..W.E",".PARIEREN.BIRNE.L","....N...E..N..I..","..INGWER......N.."],"fragen":[[1,"A",0,1,"HALLOWEEN","Gruselfest Ende Oktober"],[5,"A",2,0,"KERNOEL","Dunkelgrünes Öl aus der Steiermark"],[6,"A",2,9,"APFELMUS","Beilage zu Reibekuchen"],[9,"A",5,12,"LAUB","Fällt im Herbst von den Bäumen"],[11,"A",8,1,"PREISELBEERE","Rote Beilage zum Wildbraten"],[15,"A",11,11,"MARONE","Essbare Edelkastanie"],[16,"A",12,1,"PUERIEREN","Mit dem Stabmixer fein machen"],[17,"A",14,1,"PARIEREN","Fleisch von Sehnen und Fett befreien"],[18,"A",14,10,"BIRNE","Kernobst, unten bauchig"],[19,"A",16,2,"INGWER","Scharfe Wurzel aus Asien"],[2,"D",0,6,"WILDSCHWEIN","Borstiges Tier aus dem Wald"],[3,"D",0,13,"PILZRAHM","Sahnige Sauce mit Waldpilzen"],[4,"D",1,10,"SPAETZLE","Schwäbische Eierteigware"],[7,"D",4,2,"LATERNE","Leuchte, auch für Umzüge"],[8,"D",4,8,"KUERBISKERNE","Grüne Saat, geröstet als Topping"],[10,"D",6,4,"PFIFFERLING","Gelber Waldpilz"],[12,"D",8,11,"ROSMARIN","Nadelkraut für Kartoffeln und Lamm"],[13,"D",8,16,"ZWIEBEL","Bringt Tränen beim Schneiden"],[14,"D",10,14,"ROTWEIN","Für Jus und Schmorgerichte"]],"loesung":{"wort":"KUERBIS","anzeige":"KÜRBIS","felder":[[4,8],[5,14],[0,8],[10,14],[14,10],[15,14],[10,8]]}},"aufloesung":9},
