    raetsel: {"fehlerbild":{"titel":"Finde die 10 Fehler","a":"magazin/raetsel/nr11-martinsgans-a.svg","b":"magazin/raetsel/nr11-martinsgans-b.svg","loesung":"magazin/raetsel/nr11-martinsgans-loesung.svg","fehler":[[88,38,23,"An der Bonleiste hängt ein Zettel weniger"],[180,92,24,"Eine Wärmelampe ist aus"],[306,40,16,"Vollmond statt Mondsichel"],[350,84,16,"Eine Laterne leuchtet blau statt rot"],[124,158,13,"Auf dem Teller liegt ein Kloß weniger"],[160,159,13,"Auf der Platte fehlt ein Bratapfel"],[296,158,27,"Die Wirsingschüssel ist golden statt rot"],[362,161,17,"Die Klingel ist silbern statt golden"],[40,205,27,"Das Geschirrtuch hat blaue Streifen"],[200,207,20,"An der mittleren Tür fehlt der Griff"]]},"kreuzwort":{"titel":"Gans, Wild & Kohl","zeilen":["ROTKOHL.BEIFUSS..","...U....R........","APFEL..SAUERKRAUT","...C....T.......H",".B.H.H.KEULE....Y",".R.E.I..N....B..M",".U.N.R..T..M.R..I",".S.G.S..H..A.A..A",".TRANCHIERBRETT.N","P..R.H..R..T.E...","A..N.G..M..I.N..M","S....U.BON.N.S..A","SCHMALZ.M..S.A..R",".....A..E..G.F..O","KLOESSE.T..A.T..N",".....C..E..N....E",".....H.ARROSIEREN"],"fragen":[[1,"A",0,0,"ROTKOHL","Violettes Kohlgemüse, oft mit Apfel"],[3,"A",0,8,"BEIFUSS","Kraut, das fette Braten bekömmlich macht"],[4,"A",2,0,"APFEL","Kernobst, das man jeden Tag essen soll"],[5,"A",2,7,"SAUERKRAUT","Gegorener Weißkohl"],[9,"A",4,7,"KEULE","Bein von Geflügel oder Wild"],[12,"A",8,1,"TRANCHIERBRETT","Holzbrett mit Saftrille"],[15,"A",11,7,"BON","Bestellzettel aus der Kasse"],[16,"A",12,0,"SCHMALZ","Ausgelassenes Fett, aufs Brot"],[17,"A",14,0,"KLOESSE","Runde Beilage aus Kartoffeln"],[18,"A",16,7,"ARROSIEREN","Braten mit heißem Fett übergießen"],[2,"D",0,3,"KUECHENGARN","Zum Binden von Rouladen und Braten"],[3,"D",0,8,"BRATENTHERMOMETER","Misst die Kerntemperatur"],[6,"D",2,16,"THYMIAN","Kleinblättriges Kraut aus dem Süden"],[7,"D",4,1,"BRUST","Helles Fleisch beim Geflügel"],[8,"D",4,5,"HIRSCHGULASCH","Geschmortes vom Rotwild"],[10,"D",5,13,"BRATENSAFT","Grundlage für die Soße"],[11,"D",6,11,"MARTINSGANS","Festbraten im November"],[13,"D",9,0,"PASS","Ausgabetheke zwischen Küche und Service"],[14,"D",10,16,"MARONEN","Glasiert als Beilage zur Gans"]],"loesung":{"wort":"LATERNE","anzeige":"LATERNE","felder":[[12,5],[8,3],[0,2],[9,13],[9,8],[11,11],[13,8]]}},"aufloesung":10},
